'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "width": 335.0,
  "height": 140,
  "autosize": {
    "type": "pad"
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "cornerRadiusTopLeft": 6,
        "cornerRadiusTopRight": 6
      },
      "encoding": {
        "x": {
          "field": "Lead Time Band",
          "type": "ordinal",
          "sort": [
            "Same day",
            "1-2 days",
            "3-7 days",
            "8-14 days",
            "15-30 days",
            "31+ days"
          ],
          "title": null,
          "scale": {
            "domain": [
              "Same day",
              "1-2 days",
              "3-7 days",
              "8-14 days",
              "15-30 days",
              "31+ days"
            ],
            "paddingInner": 0.35
          },
          "axis": {
            "labelAngle": 0,
            "labelExpr": "replace(datum.label, '' days'', ''d'')",
            "labelColor": "#344054"
          }
        },
        "y": {
          "field": "Baseline No-show Rate",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              0.2
            ]
          },
          "axis": null
        },
        "color": {
          "field": "Baseline No-show Rate",
          "type": "quantitative",
          "legend": null,
          "scale": {
            "range": [
              "#BDB2F0",
              "#33287A"
            ]
          }
        },
        "tooltip": [
          {
            "field": "Lead Time Band"
          },
          {
            "field": "Baseline No-show Rate",
            "format": ".1%"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "dy": -8,
        "fontSize": 10.5,
        "fontWeight": 600,
        "color": "#101828"
      },
      "encoding": {
        "x": {
          "field": "Lead Time Band",
          "type": "ordinal",
          "sort": [
            "Same day",
            "1-2 days",
            "3-7 days",
            "8-14 days",
            "15-30 days",
            "31+ days"
          ],
          "title": null,
          "scale": {
            "domain": [
              "Same day",
              "1-2 days",
              "3-7 days",
              "8-14 days",
              "15-30 days",
              "31+ days"
            ],
            "paddingInner": 0.35
          },
          "axis": {
            "labelAngle": 0,
            "labelExpr": "replace(datum.label, '' days'', ''d'')",
            "labelColor": "#344054"
          }
        },
        "y": {
          "field": "Baseline No-show Rate",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              0.2
            ]
          },
          "axis": null
        },
        "text": {
          "field": "Baseline No-show Rate",
          "format": ".1%"
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "max",
              "field": "All-clinic Baseline No-show Rate",
              "as": "net"
            }
          ]
        }
      ],
      "mark": {
        "type": "rule",
        "strokeDash": [
          4,
          3
        ],
        "color": "#344054",
        "opacity": 0.55
      },
      "encoding": {
        "y": {
          "field": "net",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              0.2
            ]
          }
        }
      }
    }
  ]
}'

